import json from "./layers.json";
import type { ViewInfo } from "@/components/HomeMap";

// Generated by scripts/extract_layers.py — never edit the JSON by hand. The list of home-map views (each
// view's features are in public/layers/<id>.json, fetched by the map) and the ward outline to draw on.
